static void siphon_shift84(Siphon84*s,int gap){if(s->disarm||s->cooldown||s->rearm)s->bornTick+=gap;}
static void siphon_resume84(void){int gap=g.tick-ex.siphonLastTick84-1;if(gap>0){pc_siphon_shift84(gap);ex.siphonStart84+=gap;for(int i=0;i<MAXE;i++)if(g.enemies[i].on)siphon_shift84(&g.enemies[i].siphon84,gap);for(int i=0;i<32;i++)if(ex.env.hazards[i].on)siphon_shift84(&ex.env.hazards[i].siphon84,gap);if(ex.giant.active)siphon_shift84(&ex.giant.siphon84,gap);}ex.siphonLastTick84=g.tick;}
static void siphon_step84(void){if(g.mode!=1)return;for(int i=0;i<MAXE;i++)if(g.enemies[i].on)siphon_tick84(&g.enemies[i].siphon84,0);for(int i=0;i<32;i++)if(ex.env.hazards[i].on)siphon_tick84(&ex.env.hazards[i].siphon84,0);Giant*b=&ex.giant;if(b->active){if(b->morph||b->openingTicks||b->growthTicks)b->siphon84.disarm=b->siphon84.rearm=0;siphon_tick84(&b->siphon84,1);}}
